import torch


def gen_inputs(ctx, device):
    shape = ctx["x__shape"]
    d = ctx["x__dtype"]
    if isinstance(d, str):
        d = getattr(torch, d.replace("torch.", ""))
    base = torch.empty(shape, device=device, dtype=torch.float32).uniform_(-4.0, 4.0)
    inp = torch.sigmoid(base).to(dtype=d)
    return {"x": inp}


def run_correctness(x):
    x.copy_(torch.logit(x.float(), eps=1e-6).to(x.dtype))
    return x


def run(x):
    return x.logit_(eps=1e-6)
